--
-- Name: pg_trgm; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;


--
-- Name: EXTENSION pg_trgm; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION pg_trgm IS 'text similarity measurement and index searching based on trigrams';


--
-- Name: uuid-ossp; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA public;


--
-- Name: EXTENSION "uuid-ossp"; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION "uuid-ossp" IS 'generate universally unique identifiers (UUIDs)';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: alembic_version; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alembic_version (
    version_num character varying(32) NOT NULL
);


--
-- Name: booking; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.booking (
    id uuid NOT NULL,
    vendor_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    service_id uuid,
    booking_number character varying(20) NOT NULL,
    service_name character varying(255),
    service_price numeric(12,2),
    booking_date date NOT NULL,
    start_time time without time zone,
    end_time time without time zone,
    duration_minutes integer,
    status character varying(30) NOT NULL,
    customer_name character varying(255),
    customer_email character varying(255),
    customer_phone character varying(20),
    notes text,
    cancel_reason text,
    assigned_to uuid,
    subtotal numeric(12,2),
    tax_amount numeric(12,2),
    discount_amount numeric(12,2),
    total numeric(12,2),
    payment_status character varying(20),
    payment_method character varying(30),
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    confirmed_at timestamp with time zone,
    completed_at timestamp with time zone,
    invoice_id uuid,
    order_id uuid,
    assigned_staff_id uuid,
    assigned_staff_name character varying(255),
    completed_by_id uuid,
    completed_by_name character varying(255),
    delivery_notes text,
    internal_notes text,
    status_history jsonb DEFAULT '[]'::jsonb,
    followups jsonb DEFAULT '[]'::jsonb,
    attachments jsonb DEFAULT '[]'::jsonb
);


--
-- Name: bundle; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bundle (
    id uuid NOT NULL,
    vendor_id uuid NOT NULL,
    name character varying(255) NOT NULL,
    slug character varying(255) NOT NULL,
    description text,
    discount_type character varying(20) DEFAULT 'none'::character varying,
    discount_value numeric(12,2) DEFAULT '0'::numeric,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: bundle_item; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bundle_item (
    id uuid NOT NULL,
    bundle_id uuid NOT NULL,
    product_id uuid NOT NULL,
    quantity integer DEFAULT 1 NOT NULL,
    sort_order integer DEFAULT 0
);


--
-- Name: cart; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cart (
    id uuid NOT NULL,
    vendor_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    items jsonb,
    coupon_code character varying(50),
    discount_amount numeric(12,2),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: coupon; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.coupon (
    id uuid NOT NULL,
    vendor_id uuid NOT NULL,
    code character varying(50) NOT NULL,
    title character varying(255),
    description text,
    discount_type character varying(20) NOT NULL,
    discount_value numeric(12,2) NOT NULL,
    max_discount numeric(12,2),
    min_order_amount numeric(12,2),
    usage_limit integer,
    usage_per_customer integer,
    times_used integer,
    applicable_to character varying(20),
    applicable_ids jsonb,
    starts_at timestamp with time zone,
    expires_at timestamp with time zone,
    is_active boolean,
    is_public boolean,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: coupon_usage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.coupon_usage (
    id uuid NOT NULL,
    coupon_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    order_id uuid,
    discount_applied numeric(12,2),
    used_at timestamp with time zone DEFAULT now()
);


--
-- Name: crm_account; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_account (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    vendor_id uuid NOT NULL,
    parent_id uuid,
    name character varying(255) NOT NULL,
    industry character varying(100),
    region character varying(100),
    website character varying(500),
    phone character varying(50),
    email character varying(255),
    annual_revenue numeric(14,2),
    employee_count integer,
    billing_address jsonb DEFAULT '{}'::jsonb,
    shipping_address jsonb DEFAULT '{}'::jsonb,
    tags jsonb DEFAULT '[]'::jsonb,
    custom_fields jsonb DEFAULT '{}'::jsonb,
    notes text,
    owner_id uuid,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
